from collections import Counter


def _merge(symbols, pair):
    """Replace every non-overlapping occurrence of `pair` in the list of symbols, scanning left to right."""
    merged, i = [], 0
    while i < len(symbols):
        if i + 1 < len(symbols) and (symbols[i], symbols[i + 1]) == pair:
            merged.append(symbols[i] + symbols[i + 1])
            i += 2
        else:
            merged.append(symbols[i])
            i += 1
    return merged


def train_bpe(corpus, num_merges):
    frequencies = Counter(corpus)
    words = {word: list(word) for word in frequencies}
    merges = []
    for _ in range(num_merges):
        counts = Counter()
        for word, symbols in words.items():
            for pair in zip(symbols, symbols[1:]):
                counts[pair] += frequencies[word]
        if not counts:
            break
        best = min(counts, key=lambda pair: (-counts[pair], pair))     # most frequent; the smallest pair on a tie
        merges.append(best)
        words = {word: _merge(symbols, best) for word, symbols in words.items()}
    return merges


def bpe_encode(word, merges):
    symbols = list(word)
    for pair in merges:
        symbols = _merge(symbols, pair)
    return symbols
